comment on column public."notificacion"."usuario_id" is 'La persona que recibe el aviso.';
comment on column public."opcion_voto"."created_at" is 'Cuándo se creó la fila.';
comment on column public."opcion_voto"."etiqueta" is 'Texto de la opción que se vota.';
comment on column public."opcion_voto"."id" is 'Identificador de la fila.';
comment on column public."opcion_voto"."orden" is 'Posición de la opción en la encuesta.';
comment on column public."opcion_voto"."publicacion_id" is 'La encuesta a la que pertenece.';
comment on column public."opcion_voto"."updated_at" is 'Cuándo se cambió por última vez.';
comment on column public."pago_cuota"."created_at" is 'Cuándo se creó la fila.';
comment on column public."pago_cuota"."cuota_id" is 'La cuota de administración (el mes) a la que corresponde este pago.';
comment on column public."pago_cuota"."id" is 'Identificador de la fila.';
